    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(17, 24, 39, 0.9);
        --panel-border: rgba(148, 163, 184, 0.16);
        --text: #e5e7eb;
        --muted: #94a3b8;
        --accent: #f59e0b;
        --accent-soft: rgba(245, 158, 11, 0.14);
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(245, 158, 11, 0.14), transparent 34%),
          radial-gradient(circle at 80% 20%, rgba(59, 130, 246, 0.12), transparent 24%),
          linear-gradient(180deg, #040814 0%, var(--bg) 100%);
      }

      .page {
        width: min(920px, calc(100% - 32px));
        margin: 0 auto;
        padding: 48px 0 64px;
      }

      .hero {
        margin-bottom: 24px;
        padding: 28px;
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(17, 24, 39, 0.75));
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 14px;
        padding: 8px 12px;
        border: 1px solid rgba(245, 158, 11, 0.22);
        border-radius: 999px;
        background: var(--accent-soft);
        color: #fbbf24;
        font-size: 0.85rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 10px;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        max-width: 64ch;
        color: var(--muted);
        font-size: 1.02rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 14px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        overflow: hidden;
        background: rgba(15, 23, 42, 0.82);
        box-shadow: 0 10px 40px rgba(0, 0, 0, 0.24);
      }

      .question {
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        padding: 20px 22px;
        border: 0;
        background: transparent;
        color: var(--text);
        cursor: pointer;
        text-align: left;
        font: inherit;
      }

      .question:hover {
        background: rgba(148, 163, 184, 0.06);
      }

      .question:focus-visible {
        outline: 2px solid rgba(245, 158, 11, 0.9);
        outline-offset: -2px;
      }

      .question-text {
        display: block;
        font-size: 1.05rem;
        font-weight: 650;
        line-height: 1.45;
      }

      .chevron {
        flex: 0 0 auto;
        width: 38px;
        height: 38px;
        border-radius: 999px;
