        margin-top: 12px;
      }

      .accent {
        color: #fde68a;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 920px);
          padding-top: 20px;
        }

        .hero,
        .question,
        .details {
          padding-left: 18px;
          padding-right: 18px;
        }

        .hero {
          padding-top: 22px;
          padding-bottom: 22px;
          border-radius: 18px;
        }

        .question-text {
          font-size: 1rem;
        }
      }
    </style>
  </head>
  <body>
    <main class="page" id="app"></main>

    <script>
      const faqData = [
        {
          question: "Why do cats purr?",
          answer: [
            "Cats often purr when they feel safe, relaxed, or pleased, but purring can also happen when they are nervous, injured, or seeking comfort.",
            "Think of it as a flexible communication tool, not just a sign of happiness."
          ]
        },
        {
          question: "How much sleep do cats need?",
          answer: [
            "Most adult cats sleep 12 to 16 hours a day, and kittens or senior cats may sleep even more.",
            "That marathon napping helps them conserve energy for their bursts of play, hunting, and dramatic hallway sprints."
          ]
        },
        {
          question: "Why do cats knead blankets?",
          answer: [
            "Kneading is a comforting behavior cats learn as kittens when nursing.",
            "Adult cats often knead when they are content, marking a favorite resting spot with scent glands in their paws."
          ]
        },
        {
          question: "Should I feed my cat wet or dry food?",
          answer: [
            "Both can work well. Wet food adds hydration, while dry food is convenient and easy to store.",
            "The best choice depends on your cat's age, health, and preferences, so a vet can help you tailor the diet."
          ]
        },
        {
          question: "Why do cats stare at nothing?",
          answer: [
            "Cats have excellent hearing and vision, so they may notice tiny sounds or movements you miss entirely.",
            "Sometimes they are simply zoning out with the confidence of a creature that knows it runs the house."
          ]
        }
      ];

      function createQuestionIcon() {
        const span = document.createElement("span");
        span.className = "chevron";
        span.setAttribute("aria-hidden", "true");
        span.textContent = "⌄";
        return span;
      }

      function FAQItem(item) {
        const section = document.createElement("div");
        section.className = "example";
        section.dataset.open = "false";

        const button = document.createElement("button");
        button.className = "question";
        button.type = "button";
        button.setAttribute("aria-expanded", "false");

        const text = document.createElement("span");
        text.className = "question-text";
        text.textContent = item.question;

        button.append(text, createQuestionIcon());

        const details = document.createElement("div");
        details.className = "details";

        item.answer.forEach((paragraph, index) => {
          const p = document.createElement("p");
          if (index === 0) {
            const firstWord = paragraph.split(" ")[0];
            p.innerHTML = `<span class="accent">${firstWord}</span>${paragraph.slice(firstWord.length)}`;
          } else {
            p.textContent = paragraph;
          }
          details.appendChild(p);
        });

        button.addEventListener("click", () => {
          const isOpen = section.dataset.open === "true";
          section.dataset.open = String(!isOpen);
          button.setAttribute("aria-expanded", String(!isOpen));
        });

        section.append(button, details);
        return section;
      }

      function App() {
        const root = document.getElementById("app");

        const hero = document.createElement("header");
        hero.className = "hero";
        hero.innerHTML = `
          <div class="eyebrow">Cat FAQ</div>
          <h1>Everything you wanted to know about cats</h1>
          <p class="subtitle">
            A compact FAQ with answers to the most common feline mysteries.
            Tap a question to expand its answer.
          </p>
        `;

        const faq = document.createElement("section");
        faq.className = "faq";
        faq.setAttribute("aria-label", "Frequently asked questions about cats");

        faqData.forEach((item) => {
          faq.appendChild(FAQItem(item));
        });

        root.append(hero, faq);
      }

      App();
    </script>
  </body>
</html>
