    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(17, 24, 39, 0.9);
        --panel-border: rgba(148, 163, 184, 0.16);
        --text: #e5e7eb;
        --muted: #94a3b8;
        --accent: #f59e0b;
        --accent-soft: rgba(245, 158, 11, 0.14);
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(245, 158, 11, 0.14), transparent 34%),
          radial-gradient(circle at 80% 20%, rgba(59, 130, 246, 0.12), transparent 24%),
          linear-gradient(180deg, #040814 0%, var(--bg) 100%);
      }

      .page {
        width: min(920px, calc(100% - 32px));
        margin: 0 auto;
        padding: 48px 0 64px;
      }

      .hero {
        margin-bottom: 24px;
        padding: 28px;
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(17, 24, 39, 0.75));
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 14px;
        padding: 8px 12px;
        border: 1px solid rgba(245, 158, 11, 0.22);
        border-radius: 999px;
        background: var(--accent-soft);
        color: #fbbf24;
        font-size: 0.85rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 10px;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        max-width: 64ch;
        color: var(--muted);
        font-size: 1.02rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 14px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        overflow: hidden;
        background: rgba(15, 23, 42, 0.82);
        box-shadow: 0 10px 40px rgba(0, 0, 0, 0.24);
      }

      .question {
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        padding: 20px 22px;
        border: 0;
        background: transparent;
        color: var(--text);
        cursor: pointer;
        text-align: left;
        font: inherit;
      }

      .question:hover {
        background: rgba(148, 163, 184, 0.06);
      }

      .question:focus-visible {
        outline: 2px solid rgba(245, 158, 11, 0.9);
        outline-offset: -2px;
      }

      .question-text {
        display: block;
        font-size: 1.05rem;
        font-weight: 650;
        line-height: 1.45;
      }

      .chevron {
        flex: 0 0 auto;
        width: 38px;
        height: 38px;
        border-radius: 999px;
        display: grid;
        place-items: center;
        color: #fbbf24;
        background: rgba(245, 158, 11, 0.12);
        transition: transform 180ms ease, background 180ms ease;
      }

      .example[data-open="true"] .chevron {
        transform: rotate(180deg);
        background: rgba(245, 158, 11, 0.2);
      }

      .details {
        display: none;
        padding: 0 22px 22px;
        color: var(--muted);
        line-height: 1.75;
      }

      .example[data-open="true"] .details {
        display: block;
      }

      .details p {
        margin: 0;
      }

      .details p + p {
        margin-top: 12px;
      }

      .accent {
        color: #fde68a;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 920px);
          padding-top: 20px;
        }

        .hero,
        .question,
        .details {
          padding-left: 18px;
          padding-right: 18px;
        }

        .hero {
          padding-top: 22px;
          padding-bottom: 22px;
          border-radius: 18px;
        }

        .question-text {
          font-size: 1rem;
        }
      }
    </style>
  </head>
  <body>
    <main class="page" id="app"></main>

    <script>
      const faqData = [
        {
          question: "Why do cats purr?",
          answer: [
            "Cats often purr when they feel safe, relaxed, or pleased, but purring can also happen when they are nervous, injured, or seeking comfort.",
            "Think of it as a flexible communication tool, not just a sign of happiness."
          ]
        },
        {
          question: "How much sleep do cats need?",
          answer: [
            "Most adult cats sleep 12 to 16 hours a day, and kittens or senior cats may sleep even more.",
            "That marathon napping helps them conserve energy for their bursts of play, hunting, and dramatic hallway sprints."
          ]
        },
        {
          question: "Why do cats knead blankets?",
          answer: [
            "Kneading is a comforting behavior cats learn as kittens when nursing.",
            "Adult cats often knead when they are content, marking a favorite resting spot with scent glands in their paws."
          ]
        },
        {
          question: "Should I feed my cat wet or dry food?",
          answer: [
            "Both can work well. Wet food adds hydration, while dry food is convenient and easy to store.",
            "The best choice depends on your cat's age, health, and preferences, so a vet can help you tailor the diet."
          ]
        },
        {
          question: "Why do cats stare at nothing?",
          answer: [
            "Cats have excellent hearing and vision, so they may notice tiny sounds or movements you miss entirely.",
            "Sometimes they are simply zoning out with the confidence of a creature that knows it runs the house."
          ]
        }
      ];

      function createQuestionIcon() {
        const span = document.createElement("span");
        span.className = "chevron";
        span.setAttribute("aria-hidden", "true");
        span.textContent = "⌄";
        return span;
      }

      function FAQItem(item) {
        const section = document.createElement("div");
        section.className = "example";
        section.dataset.open = "false";

        const button = document.createElement("button");
        button.className = "question";
        button.type = "button";
        button.setAttribute("aria-expanded", "false");

        const text = document.createElement("span");
        text.className = "question-text";
        text.textContent = item.question;

        button.append(text, createQuestionIcon());

        const details = document.createElement("div");
        details.className = "details";

        item.answer.forEach((paragraph, index) => {
          const p = document.createElement("p");
          if (index === 0) {
            const firstWord = paragraph.split(" ")[0];
            p.innerHTML = `<span class="accent">${firstWord}</span>${paragraph.slice(firstWord.length)}`;
          } else {
            p.textContent = paragraph;
          }
          details.appendChild(p);
        });

        button.addEventListener("click", () => {
          const isOpen = section.dataset.open === "true";
          section.dataset.open = String(!isOpen);
          button.setAttribute("aria-expanded", String(!isOpen));
        });

        section.append(button, details);
        return section;
      }

      function App() {
        const root = document.getElementById("app");

        const hero = document.createElement("header");
        hero.className = "hero";
        hero.innerHTML = `
          <div class="eyebrow">Cat FAQ</div>
          <h1>Everything you wanted to know about cats</h1>
          <p class="subtitle">
            A compact FAQ with answers to the most common feline mysteries.
            Tap a question to expand its answer.
          </p>
        `;

        const faq = document.createElement("section");
        faq.className = "faq";
        faq.setAttribute("aria-label", "Frequently asked questions about cats");

        faqData.forEach((item) => {
          faq.appendChild(FAQItem(item));
        });

        root.append(hero, faq);
      }

      App();
    </script>
  </body>
</html>
